import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"mysql主从复制","description":"","frontmatter":{"title":"mysql主从复制","date":"2020-10-15T09:17:15.000Z","tags":["mysql"]},"headers":[],"relativePath":"blogs/middleware/mysql/mysql主从复制.md","filePath":"blogs/middleware/mysql/mysql主从复制.md","lastUpdated":1787477097000}`),a={name:`blogs/middleware/mysql/mysql主从复制.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h5 id="_1、主从复制的基本原理" tabindex="-1">1、主从复制的基本原理 <a class="header-anchor" href="#_1、主从复制的基本原理" aria-label="Permalink to “1、主从复制的基本原理”">​</a></h5><p>slave会从master读取binlog来进行数据同步。主要有以下三个步骤：</p><ol><li>master将改变记录到二进制日志（binary log），这些记录过程叫做二进制日志事件（binary log events）。</li><li>slave将master的binary log events拷贝到中继日志（relay log）。</li><li>slave重做中继日志中的事件，将改变应用到自己的数据库中。MySQL的复制是异步且串行化的。</li></ol><h5 id="_2、主从复制的规则" tabindex="-1">2、主从复制的规则 <a class="header-anchor" href="#_2、主从复制的规则" aria-label="Permalink to “2、主从复制的规则”">​</a></h5><ol><li><p>每个slave只能有一个master。（一对一）</p></li><li><p>每个slave只能有一个唯一的服务器ID。</p></li><li><p>每个master可以有多个slave。（一对多）</p><p>在主从复制过程中，最大的问题就是延时。</p></li></ol><h4 id="my-cnf配置" tabindex="-1">my.cnf配置 <a class="header-anchor" href="#my-cnf配置" aria-label="Permalink to “my.cnf配置”">​</a></h4><h5 id="innodb-flush-log-at-trx-commit" tabindex="-1">innodb_flush_log_at_trx_commit <a class="header-anchor" href="#innodb-flush-log-at-trx-commit" aria-label="Permalink to “innodb_flush_log_at_trx_commit”">​</a></h5><blockquote><p>0：log buffer 将每秒一次地写入到 log file中，并且 log file的flush（刷到磁盘）操作同时进行。该模式下在事务提交的时候，不会主动触发写入磁盘的操作。（该模式速度最快，但不太安全，mysqld进程的崩溃会导致上一秒钟所有事务数据的丢失。）</p><p>1： 每次事务提交时MySQL都会把log buffer的数据写入log file，并且flush(刷到磁盘)中去，该模式为系统默认该模式是。最安全的， 但也是最慢的一种方式。在mysqld 服务崩溃或者服务器主机crash的情况下，binary log 只有可能丢失最多一个语句或者一个事务。</p><p>2：每次事务提交时MySQL都会把log buffer的数据写入log file，但是flush(刷到磁盘)操作并不会同时进行。该模式下，MySQL会每秒执行一次 flush(刷到磁盘)操作。当设置为2，该模式速度较快，也比0安全，只有在操作系统崩溃或者系统断电的情况下，上一秒钟所有事务数据才可能丢失。</p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};